(()=>{"use strict";function medidaCtrl($scope,mS,_modalSvc,FileSaver,_nombreModal,toast){$scope.data={},$scope.medidas=[],$scope.dataSearch={pageIndex:1,pageSize:10},$scope.totalRecords=0,$scope.recordsQuantity=[5,10,25,50],$scope.getMedidas=()=>{mS.getData("get","/Medida/Get?json="+JSON.stringify($scope.dataSearch)).then(response=>{0!=response.code?($scope.medidas=JSON.parse(response.data)||[],$scope.totalRecords=$scope.medidas.length>0?$scope.medidas[0].totalRecords:0):toast.toastr("warning",response.message,response.titleSms)})},$scope.getMedidas(),$scope.pagechanged=()=>{$scope.getMedidas()},$scope.changePageSize=()=>{$scope.dataSearch.pageIndex=1,$scope.getMedidas()},$scope.exportTableToExcel=()=>{try{showLoader();const medidas=$scope.medidas.map(item=>({codigo:item.codigo,descripcion:item.descripcion}));_commonSvc.exportTableToExcel({arr:medidas,fileName:"SubFamilias"})}catch(error){hideLoader(),console.log(error)}},$scope.openModalNew=async()=>{let{medida:medida}=_nombreModal;const{ModalMedidaCtrl:ModalMedidaCtrl}=await import(`./../../modal/${medida.MODAL_CTRL}`),modalDialogRef=_modalSvc.openModalCustom({controller:ModalMedidaCtrl,template:`Medida/${medida.MODAL_CSHTML}`,size:"md"});modalDialogRef.result.then(result=>{"object"==typeof result&&$scope.getMedidas()})},$scope.openModalUpdate=async item=>{let{medida:medida}=_nombreModal;const{ModalMedidaCtrl:ModalMedidaCtrl}=await import(`./../../modal/${medida.MODAL_CTRL}`),uibModalRef=_modalSvc.openModalSecond(ModalMedidaCtrl,`Medida/${medida.MODAL_CSHTML}`,"md",item);uibModalRef.result.then(result=>{"object"==typeof result&&$scope.getMedidas()})},$scope.delete=function(data){Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar esta Medida ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1}).then(result=>{result.value&&mS.getData("delete","/Medida/Delete?id="+data.idMedida).then(response=>{if("0"!=response.code)return"1"==response.code?(toast.toastr("success",response.message,response.titleSms),void $scope.getMedidas()):void 0;toast.toastr("warning",response.message,response.titleSms)})})},$("#agregar").on("hide.bs.modal",e=>{$scope.get(),$scope.data={}})}angular.module("acontPlusApp").controller("medidaCtrl",medidaCtrl),medidaCtrl.$inject=["$scope","mainService","modalService","FileSaver","nombreModal","toastService"]})(window.angular);